import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Find highly correlated pairs
    corr_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                corr_pairs.add((min(fid1,fid2), max(fid1,fid2)))

    # Remove near-duplicates
    keep_ids = set(feats.ids)
    for p1, p2 in corr_pairs:
        if p2 in keep_ids:
            keep_ids.remove(p2)

    # Score features by effect size and correlation to outcome
    scores = []
    for fid in keep_ids:
        idx = feats.column(fid)
        y1 = feats.x[feats.y==1, idx]
        y0 = feats.x[feats.y==0, idx]
        tstat, _ = stats.ttest_ind(y1, y0, equal_var=False)
        scores.append((fid, abs(tstat)))

    # Sort by score
    scores.sort(key=lambda x: x[1], reverse=True)

    # Check for interaction terms
    candidates = [fid for fid, _ in scores[:10]]
    interactions = []

    for i, fid1 in enumerate(candidates):
        for j, fid2 in enumerate(candidates[i+1:], i+1):
            if (min(fid1,fid2), max(fid1,fid2)) not in corr_pairs:
                # Compute interaction score
                idx1 = feats.column(fid1)
                idx2 = feats.column(fid2)
                prod = feats.x[:,idx1] * feats.x[:,idx2]
                mi = mutual_info_classif(prod.reshape(-1,1), feats.y)[0]
                interactions.append((fid1, fid2, mi))

    # Sort interactions by MI
    interactions.sort(key=lambda x: x[2], reverse=True)

    # Return best interaction if significant
    if interactions and interactions[0][2] > 0.05:
        f1, f2, _ = interactions[0]
        return Design(
            drivers=(f1, f2),
            columns=(f1, f2),
            products=((f1, f2),),
            loadings={f1: 1.0, f2: 1.0}
        )

    # Otherwise return top single feature
    if scores:
        top_fid = scores[0][0]
        return Design(
            drivers=(top_fid,),
            columns=(top_fid,),
            products=(),
            loadings={top_fid: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

